// let's imagine this file is autogenerated from the backend
// ideally, we want to keep these api related types in sync
// with the backend instead of manually writing them out

export type BaseEntity = {
  id: string;
  createdAt: number;
};

export type Entity<T> = {
  [K in keyof T]: T[K];
} & BaseEntity;

export type Meta = {
  page: number;
  total: number;
  totalPages: number;
};

export type User = Entity<{
  firstName: string;
  lastName: string;
  email: string;
  role: 'ADMIN' | 'USER';
  teamId: string;
  bio: string;
}>;

export type AuthResponse = {
  jwt: string;
  user: User;
};

export type Team = Entity<{
  name: string;
  description: string;
}>;

export type Discussion = Entity<{
  title: string;
  body: string;
  teamId: string;
  author: User;
  commentCount: number;
  lastCommentAt: number | null;
}>;

export type Comment = Entity<{
  body: string;
  discussionId: string;
  author: User;
}>;

import { useQueryClient } from '@tanstack/react-query';
import { useSearchParams } from 'react-router';

import { Link } from '@/components/ui/link';
import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { paths } from '@/config/paths';
import { formatDate } from '@/utils/format';

import { getDiscussionQueryOptions } from '../api/get-discussion';

const formatCommentInfo = (commentCount: number, lastCommentAt: number | null): string => {
  if (commentCount === 0) {
    return 'No comments yet';
  }
  return lastCommentAt ? `Last comment: ${formatDate(lastCommentAt)}` : `${commentCount} comment${commentCount > 1 ? 's' : ''}`;
};
import { useDiscussions } from '../api/get-discussions';

import { DeleteDiscussion } from './delete-discussion';

export type DiscussionsListProps = {
  onDiscussionPrefetch?: (id: string) => void;
};

export const DiscussionsList = ({
  onDiscussionPrefetch,
}: DiscussionsListProps) => {
  const [searchParams] = useSearchParams();

  const discussionsQuery = useDiscussions({
    page: +(searchParams.get('page') || 1),
  });
  const queryClient = useQueryClient();

  if (discussionsQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const discussions = discussionsQuery.data?.data;
  const meta = discussionsQuery.data?.meta;

  if (!discussions) return null;

  return (
    <Table
      data={discussions}
      columns={[
        {
          title: 'Title',
          field: 'title',
        },
        {
          title: 'Comments',
          field: 'commentCount',
          Cell({ entry: { commentCount, lastCommentAt } }) {
            return <span>{formatCommentInfo(commentCount, lastCommentAt)}</span>;
          },
        },
        {
          title: 'Created At',
          field: 'createdAt',
          Cell({ entry: { createdAt } }) {
            return <span>{formatDate(createdAt)}</span>;
          },
        },
        {
          title: '',
          field: 'id',
          Cell({ entry: { id } }) {
            return (
              <Link
                onMouseEnter={() => {
                  // Prefetch the discussion data when the user hovers over the link
                  queryClient.prefetchQuery(getDiscussionQueryOptions(id));
                  onDiscussionPrefetch?.(id);
                }}
                to={paths.app.discussion.getHref(id)}
              >
                View
              </Link>
            );
          },
        },
        {
          title: '',
          field: 'id',
          Cell({ entry: { id } }) {
            return <DeleteDiscussion id={id} />;
          },
        },
      ]}
      pagination={
        meta && {
          totalPages: meta.totalPages,
          currentPage: meta.page,
          rootUrl: '',
        }
      }
    />
  );
};

import { HttpResponse, http } from 'msw';

import { env } from '@/config/env';

import { db, persistDb, seedData } from '../db';
import {
  requireAuth,
  requireAdmin,
  sanitizeUser,
  networkDelay,
} from '../utils';

type DiscussionBody = {
  title: string;
  body: string;
};

export const discussionsHandlers = [
  http.get(`${env.API_URL}/discussions`, async ({ cookies, request }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }

      seedData();

      const url = new URL(request.url);

      const page = Number(url.searchParams.get('page') || 1);

      const total = db.discussion.count({
        where: {
          teamId: {
            equals: user?.teamId,
          },
        },
      });

      const totalPages = Math.ceil(total / 10);

      const result = db.discussion
        .findMany({
          where: {
            teamId: {
              equals: user?.teamId,
            },
          },
          take: 10,
          skip: 10 * (page - 1),
        })
        .map(({ authorId, ...discussion }) => {
          const author = db.user.findFirst({
            where: {
              id: {
                equals: authorId,
              },
            },
          });
          const comments = db.comment.findMany({
            where: {
              discussionId: {
                equals: discussion.id,
              },
            },
          });
          const commentCount = comments.length;
          const lastCommentAt = commentCount > 0
            ? comments.reduce((latest, c) => (c.createdAt > latest ? c.createdAt : latest), 0)
            : null;
          return {
            ...discussion,
            author: author ? sanitizeUser(author) : {},
            commentCount,
            lastCommentAt,
          };
        });
      return HttpResponse.json({
        data: result,
        meta: {
          page,
          total,
          totalPages,
        },
      });
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.get(
    `${env.API_URL}/discussions/:discussionId`,
    async ({ params, cookies }) => {
      await networkDelay();

      try {
        const { user, error } = requireAuth(cookies);
        if (error) {
          return HttpResponse.json({ message: error }, { status: 401 });
        }
        const discussionId = params.discussionId as string;
        const discussion = db.discussion.findFirst({
          where: {
            id: {
              equals: discussionId,
            },
            teamId: {
              equals: user?.teamId,
            },
          },
        });

        if (!discussion) {
          return HttpResponse.json(
            { message: 'Discussion not found' },
            { status: 404 },
          );
        }

        const author = db.user.findFirst({
          where: {
            id: {
              equals: discussion.authorId,
            },
          },
        });

        const comments = db.comment.findMany({
          where: {
            discussionId: {
              equals: discussion.id,
            },
          },
        });
        const commentCount = comments.length;
        const lastCommentAt = commentCount > 0
          ? comments.reduce((latest, c) => (c.createdAt > latest ? c.createdAt : latest), 0)
          : null;

        const result = {
          ...discussion,
          author: author ? sanitizeUser(author) : {},
          commentCount,
          lastCommentAt,
        };

        return HttpResponse.json({ data: result });
      } catch (error: any) {
        return HttpResponse.json(
          { message: error?.message || 'Server Error' },
          { status: 500 },
        );
      }
    },
  ),

  http.post(`${env.API_URL}/discussions`, async ({ request, cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const data = (await request.json()) as DiscussionBody;
      requireAdmin(user);
      const result = db.discussion.create({
        teamId: user?.teamId,
        authorId: user?.id,
        ...data,
      });
      await persistDb('discussion');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.patch(
    `${env.API_URL}/discussions/:discussionId`,
    async ({ request, params, cookies }) => {
      await networkDelay();

      try {
        const { user, error } = requireAuth(cookies);
        if (error) {
          return HttpResponse.json({ message: error }, { status: 401 });
        }
        const data = (await request.json()) as DiscussionBody;
        const discussionId = params.discussionId as string;
        requireAdmin(user);
        const result = db.discussion.update({
          where: {
            teamId: {
              equals: user?.teamId,
            },
            id: {
              equals: discussionId,
            },
          },
          data,
        });
        await persistDb('discussion');
        return HttpResponse.json(result);
      } catch (error: any) {
        return HttpResponse.json(
          { message: error?.message || 'Server Error' },
          { status: 500 },
        );
      }
    },
  ),

  http.delete(
    `${env.API_URL}/discussions/:discussionId`,
    async ({ cookies, params }) => {
      await networkDelay();

      try {
        const { user, error } = requireAuth(cookies);
        if (error) {
          return HttpResponse.json({ message: error }, { status: 401 });
        }
        const discussionId = params.discussionId as string;
        requireAdmin(user);
        const result = db.discussion.delete({
          where: {
            id: {
              equals: discussionId,
            },
          },
        });
        await persistDb('discussion');
        return HttpResponse.json(result);
      } catch (error: any) {
        return HttpResponse.json(
          { message: error?.message || 'Server Error' },
          { status: 500 },
        );
      }
    },
  ),
];

import { factory, primaryKey } from '@mswjs/data';
import { nanoid } from 'nanoid';

const models = {
  user: {
    id: primaryKey(nanoid),
    firstName: String,
    lastName: String,
    email: String,
    password: String,
    teamId: String,
    role: String,
    bio: String,
    createdAt: Date.now,
  },
  team: {
    id: primaryKey(nanoid),
    name: String,
    description: String,
    createdAt: Date.now,
  },
  discussion: {
    id: primaryKey(nanoid),
    title: String,
    body: String,
    authorId: String,
    teamId: String,
    createdAt: Date.now,
  },
  comment: {
    id: primaryKey(nanoid),
    body: String,
    authorId: String,
    discussionId: String,
    createdAt: Date.now,
  },
};

export const db = factory(models);

export type Model = keyof typeof models;

const dbFilePath = 'mocked-db.json';

export const loadDb = async () => {
  // If we are running in a Node.js environment
  if (typeof window === 'undefined') {
    const { readFile, writeFile } = await import('fs/promises');
    try {
      const data = await readFile(dbFilePath, 'utf8');
      return JSON.parse(data);
    } catch (error: any) {
      if (error?.code === 'ENOENT') {
        const emptyDB = {};
        await writeFile(dbFilePath, JSON.stringify(emptyDB, null, 2));
        return emptyDB;
      } else {
        console.error('Error loading mocked DB:', error);
        return null;
      }
    }
  }
  // If we are running in a browser environment
  return Object.assign(
    JSON.parse(window.localStorage.getItem('msw-db') || '{}'),
  );
};

export const storeDb = async (data: string) => {
  // If we are running in a Node.js environment
  if (typeof window === 'undefined') {
    const { writeFile } = await import('fs/promises');
    await writeFile(dbFilePath, data);
  } else {
    // If we are running in a browser environment
    window.localStorage.setItem('msw-db', data);
  }
};

export const persistDb = async (model: Model) => {
  if (process.env.NODE_ENV === 'test') return;
  const data = await loadDb();
  data[model] = db[model].getAll();
  await storeDb(JSON.stringify(data));
};

export const initializeDb = async () => {
  const database = await loadDb();
  Object.entries(db).forEach(([key, model]) => {
    const dataEntres = database[key];
    if (dataEntres) {
      dataEntres?.forEach((entry: Record<string, any>) => {
        model.create(entry);
      });
    }
  });
};

export const seedData = () => {
  // Seed some teams first so users can be linked to them
  if (db.team.getAll().length === 0) {
    const team1 = db.team.create({ name: 'Engineering', description: 'Engineering team' });
    const team2 = db.team.create({ name: 'Design', description: 'Design team' });

    // Seed users
    const user1 = db.user.create({
      firstName: 'John',
      lastName: 'Doe',
      email: 'john@bulletproof.com',
      password: '123456',
      role: 'ADMIN',
      teamId: team1.id,
      bio: 'Admin user',
    });
    const user2 = db.user.create({
      firstName: 'Jane',
      lastName: 'Smith',
      email: 'jane@bulletproof.com',
      password: '123456',
      role: 'USER',
      teamId: team1.id,
      bio: 'Regular user',
    });
    const user3 = db.user.create({
      firstName: 'Alex',
      lastName: 'Johnson',
      email: 'alex@bulletproof.com',
      password: '123456',
      role: 'ADMIN',
      teamId: team2.id,
      bio: 'Design admin',
    });

    // Seed discussions
    const discussion1 = db.discussion.create({
      title: 'Welcome to the team!',
      body: 'This is a welcome discussion for new team members.',
      authorId: user1.id,
      teamId: team1.id,
    });
    const discussion2 = db.discussion.create({
      title: 'Project roadmap Q4',
      body: 'Let us discuss the project roadmap for Q4.',
      authorId: user1.id,
      teamId: team1.id,
    });
    const discussion3 = db.discussion.create({
      title: 'Design system updates',
      body: 'Updates to our design system components.',
      authorId: user3.id,
      teamId: team2.id,
    });
    const discussion4 = db.discussion.create({
      title: 'Team building event',
      body: 'Planning our next team building event.',
      authorId: user2.id,
      teamId: team1.id,
    });

    // Seed comments on discussion1 (3 comments)
    db.comment.create({
      body: 'Thanks for the warm welcome!',
      authorId: user2.id,
      discussionId: discussion1.id,
      createdAt: Date.now() - 86400000 * 3,
    });
    db.comment.create({
      body: 'Looking forward to working with everyone!',
      authorId: user3.id,
      discussionId: discussion1.id,
      createdAt: Date.now() - 86400000 * 2,
    });
    db.comment.create({
      body: 'Let me know if you need any help getting started.',
      authorId: user1.id,
      discussionId: discussion1.id,
      createdAt: Date.now() - 86400000,
    });

    // Seed comments on discussion2 (2 comments)
    db.comment.create({
      body: 'I have some ideas for the roadmap.',
      authorId: user2.id,
      discussionId: discussion2.id,
      createdAt: Date.now() - 86400000 * 5,
    });
    db.comment.create({
      body: 'Great ideas! Let us sync on this next week.',
      authorId: user1.id,
      discussionId: discussion2.id,
      createdAt: Date.now() - 86400000 * 1,
    });

    // discussion3 has NO comments
    // discussion4 has 1 comment
    db.comment.create({
      body: 'I can help with the event planning!',
      authorId: user3.id,
      discussionId: discussion4.id,
      createdAt: Date.now() - 86400000 * 4,
    });
  }
};

export const resetDb = () => {
  window.localStorage.clear();
};

